<?php
namespace Database\Seeders;use App\Models\Testimonial;use Illuminate\Database\Seeder;
class TestimonialSeeder extends Seeder {public function run():void{if(Testimonial::exists())return;foreach([['MorMons Taste','Enrolling in Pathway was a really good decision I made for my driving education. The instructors were incredibly skilled at teaching. They have a supportive learning environment that allowed me to ask questions and make mistakes without feeling judged.'],['Sajeed Enayet Aninda',"I had a fantastic experience with Pathway Driving School. Mr. Sumon was my instructor, and he was super patient and really knew his stuff. He made learning to drive easy and enjoyable. I'd definitely recommend them if you're looking to learn from the best."]] as $i=>[$name,$review])Testimonial::create(compact('name','review')+['rating'=>5,'sort_order'=>$i,'is_active'=>true]);}}
